sections.body:
保存为 command-audit.mjs，运行 node command-audit.mjs，无额外依赖。每行是一份独立决策：前六行有真实意图，后六行的 null 表示不该行动。分数全部手写，不是录音或模型输出。

```javascript
/**
 * @file Audit command rejection with synthetic classification scores.
 * @author liliwei
 * @date 2026-11-10
 * @LastEditors liliwei
 * @LastEditTime 2026-11-10
 */
export const labels = ['left', 'right', '_unknown_', '_background_noise_'];
/** @param {number[]} scores Four normalized scores in labels order. @param {number} threshold Inclusive minimum. @param {boolean} commandOnly Demonstrate the unsafe baseline. @returns {string|null} Command or abstention. */
export function decide(scores, threshold, commandOnly = false) {
  if (!Array.isArray(scores) || scores.length !== labels.length ||
      !Array.from(scores).every(x => Number.isFinite(x) && x >= 0 && x <= 1) ||
      Math.abs(scores.reduce((a, b) => a + b, 0) - 1) > 1e-5 ||
      !Number.isFinite(threshold) || threshold < 0 || threshold > 1) {
    throw new Error('Invalid scores or threshold');
  }
  const candidates = commandOnly ? scores.slice(0, 2) : scores;
  const best = Math.max(...candidates);
  if (best < threshold || candidates.filter(x => x === best).length !== 1) return null;
  const winner = candidates.indexOf(best);
  return winner < 2 ? labels[winner] : null;
}
// Each row is one independent decision; null means no intended command.
export const samples = [
  ['left',  [.90, .04, .04, .02]],
  ['right', [.03, .90, .04, .03]],
  ['left',  [.60, .25, .10, .05]],
  ['right', [.80, .10, .05, .05]],
  ['left',  [.75, .15, .05, .05]],
  ['right', [.10, .72, .10, .08]],
  [null,    [.10, .05, .80, .05]],
  [null,    [.05, .05, .10, .80]],
  [null,    [.45, .40, .10, .05]],
  [null,    [.78, .10, .10, .02]],
  [null,    [.02, .03, .90, .05]],
  [null,    [.35, .30, .20, .15]],
];
/** @param {number} threshold Inclusive minimum. @param {boolean} commandOnly Unsafe comparison. @returns {object} Counts retaining rejected and wrong commands. */
export function audit(threshold, commandOnly = false) {
  const out = { correct: 0, wrong: 0, rejected: 0, falseTriggers: 0, negatives: 0 };
  for (const [truth, scores] of samples) {
    const prediction = decide(scores, threshold, commandOnly);
    if (truth === null) {
      out.negatives++;
      if (prediction !== null) out.falseTriggers++;
    } else if (prediction === null) out.rejected++;
    else if (prediction === truth) out.correct++;
    else out.wrong++;
  }
  return out;
}
console.log('command-only', audit(0, true));
for (const threshold of [.50, .75, .90]) console.log(threshold, audit(threshold));
```

这份简化模型只有四类，不能直接冒充公开工具的完整词表。接入真实识别器时，需要按它的实际标签表遍历全部分数；例如 up 获胜而游戏只接受左右时，也应拒绝，不能把 up 删除后再选。Float32Array 可先转换为普通数组；输入必须是概率型分数，不能拿未归一化 logits 直接套此检查。

本文门槛采用大于等于，同分明确拒绝；它是自定义规则，不照搬库回调的边界。commandOnly=true 只用于复现错误做法，不应作为生产选项。代码没有录音、训练、流式分段或操作去重，后续会话层必须另接。
